    let deviation = post_residual as f64 - mean;
    score -= 0.85 * deviation;

    // Exact matches are structurally valuable because they tend to close a bin.
    if post_residual == 0 {
        score -= 28.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // If this is the only fitting bin, opening a new bin may be preferable.
    if fitting_bins_count <= 1 {
        score += 16.0;

        let opening_penalty = (open_bins_count as f64).sqrt() * 3.0;
        score += opening_penalty * (1.0 - progress);

        if bin_residual == bin_capacity {
            score += 70.0;
        }
    } else if bin_residual == bin_capacity {
        // A new bin is attractive mainly when existing bins create bad fragmentation.
        score += 24.0 + 0.30 * mean;
    }

    // Mildly favor bins that are already relatively full, provided they fit.
    if bin_residual >= item_size {
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 8.0 * fullness * fullness;
    }

    score
}
